 const players=ps.docs.map(x=>({id:x.id,...x.data(),role:'fixed'})),reserves=rs.docs.map(x=>({id:x.id,...x.data(),role:'reserve'})),couples=cs.docs.map(x=>({id:x.id,...x.data()})).sort((a,b)=>coupleNumber(a.id,a)-coupleNumber(b.id,b));
